import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def hasdig(v, d):
    while v:
        if v % 10 == d:
            return True
        v //= 10
    return False
r = 0
for x in a:
    if hasdig(x, 4):
        r ^= x
print(r)

